<template><section class="chat"><aside><h3>在线同事</h3><el-menu><el-menu-item v-for="hr in users" :key="hr.id" @click="current=hr">{{hr.name}}（{{hr.username}}）</el-menu-item></el-menu></aside><main><template v-if="current"><h3>{{current.name}}</h3><div class="messages"><p v-for="(msg,i) in history" :key="i" :class="msg.self?'self':''">{{msg.content}}</p></div><el-input v-model="text" type="textarea" :rows="3" @keyup.ctrl.enter="send"/><el-button type="primary" @click="send" style="margin-top:8px">发送</el-button></template><el-empty v-else description="选择一位同事开始聊天"/></main></section></template>
<script setup>import {onBeforeUnmount,onMounted,ref,watch} from 'vue';import {chatUsers} from '@/api/chat.js';const users=ref([]),current=ref(),text=ref(''),history=ref([]);let socket;function frame(command,headers={},body=''){return command+'\n'+Object.entries(headers).map(([k,v])=>`${k}:${v}`).join('\n')+'\n\n'+body+'\0'}function connect(){const scheme=location.protocol==='https:'?'wss':'ws';socket=new WebSocket(`${scheme}://${location.host}/api/ws/ep`);socket.onopen=()=>socket.send(frame('CONNECT',{'accept-version':'1.2','heart-beat':'0,0'}));socket.onmessage=e=>{for(const raw of e.data.split('\0')){if(raw.startsWith('MESSAGE')){const body=raw.slice(raw.indexOf('\n\n')+2);try{const msg=JSON.parse(body);if(!current.value||msg.from===current.value.username)history.value.push({...msg,self:false})}catch{}}}}}function send(){if(!current.value||!text.value.trim()||socket?.readyState!==WebSocket.OPEN)return;const content=text.value.trim();socket.send(frame('SEND',{destination:'/app/ws/chat','content-type':'application/json'},JSON.stringify({to:current.value.username,content})));history.value.push({content,self:true});text.value=''}watch(current,()=>history.value=[]);onMounted(async()=>{users.value=(await chatUsers()).data??[];connect()});onBeforeUnmount(()=>socket?.close())</script>
<style scoped>.chat{display:flex;min-height:520px;border:1px solid #ddd}.chat aside{width:240px;border-right:1px solid #ddd;padding:12px}.chat main{flex:1;padding:16px}.messages{height:330px;overflow:auto;background:#f7f7f7;padding:12px}.messages p{background:#fff;padding:8px;border-radius:6px;width:max-content;max-width:80%}.messages .self{margin-left:auto;background:#d9fdd3}</style>
